from .stage_planning import (
    generate_stage_episode_outlines,
    validate_episode_batch,
)
from .episode_outline_review import review_episode_outlines

EXAMPLE = '[\n {"episode_id": 1, "title": "Episode title", "core_plot": "Specific actions and outcomes, approximately 120 English words",\n  "roles": ["Character name"], "highlights": "Dramatic highlights and standout moments",\n  "character_growth": "Character growth or psychological change", "relationship_changes": "Changes in relationships",\n  "main_storyline_progression": "Progress of the main plot"}\n]'
EPISODE_PROMPT = (
    "Expand the current phase's detailed event list into episode-by-episode outlines from Episode {{StartEpisodeId}} through Episode {{EndEpisodeId}}. The series has {{TotalEpisodeNums}} episodes in all. Write descriptive content in English.\n\nGenre: {{Topic}}\nWorld: {{WorldView}}\nCore premise: {{StoryOutline}}\nCharacters: {{RoleInfo}}\n\nSeries phases and episode ranges: {{StageRanges}}\nCurrent phase: {{StageName}}\nDetailed event list for this phase: {{Outline}}\nReason for its pacing allocation: {{PacingReason}}\nAlready established earlier episode outlines: {{EpisodeOutline}}\n\nRequirements:\n1. Develop the main plot along this phase's events. Add plausible subplots, action, and interaction where useful, but do not finish the phase early and fill space with later-phase events.\n2. Carry forward characters' circumstances, relationships, knowledge, event outcomes, object ownership, and unresolved conflicts. Show a cause for every change; avoid abrupt jumps in behavior, place, time, or facts.\n3. For each episode, specify what prompts an action, what blocks it, what choice follows, and what outcome it produces. For each episode, aim to center it on a focused dramatic task, deliver meaningful progress or a local payoff, and build anticipation for the next episode through a new question, a pending consequence, or a changed situation. Pace the whole series naturally; do not repeat completed events.\n4. Keep concrete action and outcome in `core_plot`. Every other field must match what actually happens there. If a character or relationship does not materially change, still accurately describe its continuing state.\n5. Episode IDs must run continuously from {{StartEpisodeId}} to {{EndEpisodeId}}, without gaps or duplicates.\n\nOutput a JSON array only. Each episode must contain exactly these eight fields:\n"
    + EXAMPLE
)
EIGHT_REVIEW_PROMPT = 'You are a rigorous continuity editor for the whole series. Read every episode outline and identify only narrative-consistency problems. Recommend fixes and score the complete outline; do not rewrite it in this pass.\n\nStory background: {{Background}}\nTotal episodes: {{Total}}\nComplete episode outlines: {{Original}}\n\nReview scope:\n1. Check continuity of identity, kinship, life and death, injuries, abilities, motives, knowledge, and relationships. Actions must fit established states and world rules. Identify logical or factual contradictions, including time and place.\n2. Check causal links, chronology, travel, world rules, power, and acquisition, possession, and use of important props and evidence. Completed events must not silently reset or recur.\n3. Check adjacent and distant episodes and consistency within each episode and across fields. Growth, relationships, main-plot progress, and highlights must match events in `core_plot`.\n4. Ground every issue in the current outlines. Name the episodes, relevant events, missing link or contradiction, and its effect. Distinguish definite contradiction from a necessary missing explanation. Do not mistake reasonable ellipsis, suspense, or behavior permitted by established rules for inconsistency.\n5. In this review, revise only for narrative coherence. Do not raise or score issues based on emotional impact, style, pacing, or personal plot preference. Evaluate foreshadowing only for consistency of information and causality. Suggest coordinated changes across episodes where needed.\n\nScoring: `total_score` is 0–100, based only on the number, severity, and scope of grounded continuity issues. `critical` means a direct clash in key identity, death, central rules, or main-plot causality affecting multiple episodes. `moderate` means a clear local-state, evidence-transfer, or inter-episode gap requiring added events or local plot revision. `minor` means an ambiguity needing slight clarification. Merge repeated manifestations of one root problem.\n100: no grounded issues. 90–99: a few minor issues. 75–89: a few moderate or several minor, no critical. 60–74: one critical or several moderate. 40–59: several critical issues materially damage continuity. 0–39: pervasive contradictions make the central narrative incoherent. Score lower within each band as breadth and number increase. Explain issue counts and deductions in `overall_assessment`; use the same standard each time.\n{% if RetryFeedback %}Previous validation feedback: {{RetryFeedback}}{% endif %}\nOutput one JSON object only. Use `critical`, `moderate`, or `minor` for severity:\n{\n "total_score": 80,\n "overall_assessment": "Continuity assessment, issue counts by severity, and scoring rationale",\n "issues": [\n  {"issue_id": "I01", "severity": "moderate", "category": "Character-state continuity",\n   "episode_ids": [1, 2], "evidence": [{"episode_id": 1, "summary": "Relevant event"}],\n   "problem": "Concrete contradiction or missing causal link", "impact": "Why it affects surrounding events",\n   "recommendation": "Fix and any coordinated changes"}\n ],\n "revision_strategy": "How to align states, causality, and transitions while preserving effective material"\n}\nIf there are no issues, output an empty `issues` array.\n'
EIGHT_REWRITE_PROMPT = (
    "You are revising the complete series outline. Check the review's evidence, repair grounded continuity issues, and output all {{Total}} episode outlines in English.\n\nStory background: {{Background}}\nCurrent complete episode outlines: {{Original}}\nReview: {{Review}}\n\nRevision requirements:\n1. Verify each review issue against the outlines. Repair contradictions in identities, states, relationships, motives, knowledge, world rules, time and place, props and evidence, event causality, and inter-episode links. Do not force an unsupported suggestion into the story.\n2. Preserve the principal characters, core story, effective events, and important clues. You may reorganize, add, remove, or replace local episode material substantially where necessary for coherence; adjust downstream effects as well.\n3. Fix other inconsistencies you notice. Show repairs as concrete events; do not make unsupported claims of narrative coherence. Every field must match its episode's `core_plot` and surrounding episodes.\n4. Keep exactly {{Total}} episodes with continuous episode_id values from 1 to {{Total}}. Give each `core_plot` approximately 120 English words of concrete action and outcome, including later episodes. Output every episode, even if unchanged.\n{% if RetryFeedback %}Previous validation feedback: {{RetryFeedback}}{% endif %}\nOutput only a JSON array, with exactly the eight fields in this example:\n"
    + EXAMPLE
)


async def review_eight_fields(episodes, common):
    return await review_episode_outlines(
        episodes,
        common,
        batch_validator=validate_episode_batch,
        review_prompt=EIGHT_REVIEW_PROMPT,
        rewrite_prompt=EIGHT_REWRITE_PROMPT,
    )


async def generate_eight_fields(story, total, common):
    return await generate_stage_episode_outlines(
        story,
        total,
        common,
        EPISODE_PROMPT,
        batch_validator=validate_episode_batch,
        review_callback=review_eight_fields,
    )
